  ) AS p(id, fee_id, student_id, amount, method, paid_on, payer, bank, ref, ord);
                            recorded_by, payer_name, payer_bank, transfer_reference, status, created_at)
  SELECT p.id, v_school, p.fee_id, p.student_id, p.amount, p.method,
         'RCP-' || lpad((row_number() OVER (PARTITION BY extract(year from p.paid_on) ORDER BY p.paid_on, p.ord))::text, 5, '0')
                || '-' || extract(year from p.paid_on)::int,
         p.paid_on, '14aefa89-4f47-5819-a136-b5cee85e306d', p.payer, p.bank, p.ref, 'success', p.paid_on + time '10:00' + (p.ord % 300) * interval '1 minute'
  FROM _demo_pay p;
  SELECT v_school, extract(year from paid_on)::int, count(*) FROM _demo_pay GROUP BY 1, 2
  ON CONFLICT (school_id, year) DO UPDATE SET last_no = EXCLUDED.last_no;
  SELECT v_school, '14aefa89-4f47-5819-a136-b5cee85e306d', 'bursar', 'payment.recorded', 'fee_payment', fp.id,
         jsonb_build_object('studentId', fp.student_id, 'feeStructureId', fp.fee_structure_id, 'amount', fp.amount_paid,
                            'method', fp.payment_method, 'paymentDate', fp.payment_date, 'receiptNo', fp.receipt_number),
         false, fp.created_at
  FROM fee_payments fp WHERE fp.school_id = v_school AND fp.payment_date >= v_cur_start ORDER BY fp.created_at;
      current_streak, longest_streak, last_study_date, total_questions_attempted, total_correct, total_xp)
  SELECT v_school, '65c6153b-dd19-5d71-96cc-cce3721ad920', ARRAY(SELECT id FROM jamb_subjects WHERE name IN ('English Language', 'Mathematics', 'Physics', 'Chemistry') ORDER BY is_compulsory DESC, name), 300,
      v_today + 190, 20, 6, 12, v_today - 1, 180, 142, 1420;
  SELECT v_school, '65c6153b-dd19-5d71-96cc-cce3721ad920', tp.id, x.att, x.cor, round(x.cor::numeric / x.att * 100), now() - (1 + (abs(hashtext(tp.id::text)) % 9)) * interval '1 day'
  FROM (SELECT jt.id, row_number() OVER (PARTITION BY jt.subject_id ORDER BY jt.id) rn FROM jamb_topics jt
        JOIN jamb_subjects js ON js.id = jt.subject_id WHERE js.name IN ('English Language', 'Mathematics', 'Physics', 'Chemistry')) tp
  CROSS JOIN LATERAL (SELECT 10 AS att, least(10, greatest(1, round(7.4 + ((abs(hashtext(tp.id::text || '65c6153b-dd19-5d71-96cc-cce3721ad920')) % 5) - 2))))::int AS cor) x
  WHERE tp.rn <= 4;
      current_streak, longest_streak, last_study_date, total_questions_attempted, total_correct, total_xp)
  SELECT v_school, 'ac75ebac-a536-57c3-aab6-c8d19a4f59c8', ARRAY(SELECT id FROM jamb_subjects WHERE name IN ('English Language', 'Mathematics', 'Economics', 'Government') ORDER BY is_compulsory DESC, name), 220,
      v_today + 190, 20, 2, 7, v_today - 2, 49, 30, 300;
  SELECT v_school, 'ac75ebac-a536-57c3-aab6-c8d19a4f59c8', tp.id, x.att, x.cor, round(x.cor::numeric / x.att * 100), now() - (2 + (abs(hashtext(tp.id::text)) % 9)) * interval '1 day'
  FROM (SELECT jt.id, row_number() OVER (PARTITION BY jt.subject_id ORDER BY jt.id) rn FROM jamb_topics jt
        JOIN jamb_subjects js ON js.id = jt.subject_id WHERE js.name IN ('English Language', 'Mathematics', 'Economics', 'Government')) tp
  CROSS JOIN LATERAL (SELECT 10 AS att, least(10, greatest(1, round(5.8 + ((abs(hashtext(tp.id::text || 'ac75ebac-a536-57c3-aab6-c8d19a4f59c8')) % 5) - 2))))::int AS cor) x
  WHERE tp.rn <= 4;
      current_streak, longest_streak, last_study_date, total_questions_attempted, total_correct, total_xp)
  SELECT v_school, '8b74c55c-8149-5a34-a910-0f5f27051106', ARRAY(SELECT id FROM jamb_subjects WHERE name IN ('English Language', 'Mathematics', 'Physics', 'Chemistry') ORDER BY is_compulsory DESC, name), 250,
      v_today + 190, 20, 2, 9, v_today - 26, 87, 35, 350;
