  INSERT INTO questions (id, school_id, created_by, type, subject, class_level, topic, question_text, options, correct_answer, explanation, marks, difficulty, is_active) VALUES
    ('46611487-877b-5b91-9aa2-5ac2c082fc90', v_school, 'a2ed6252-37b9-513c-a254-0acc72d72690', 'mcq', 'Mathematics', 'SS3', 'Linear equations', 'Solve for x: 3x − 7 = 11', '[{"key": "A", "text": "4"}, {"key": "B", "text": "6"}, {"key": "C", "text": "18"}, {"key": "D", "text": "−6"}]'::jsonb, 'B', '3x = 18, so x = 6.', 1, 'easy', true),
    ('3cf31baf-5d93-5038-88a0-c5245e35f840', v_school, 'a2ed6252-37b9-513c-a254-0acc72d72690', 'mcq', 'Mathematics', 'SS3', 'Logarithms', 'What is the value of log₁₀ 1000?', '[{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "10"}, {"key": "D", "text": "100"}]'::jsonb, 'B', '10³ = 1000.', 1, 'easy', true),
    ('a44efb75-de05-50ae-a3c1-56ea7bb7f22d', v_school, 'a2ed6252-37b9-513c-a254-0acc72d72690', 'mcq', 'Mathematics', 'SS3', 'Coordinate geometry', 'Find the gradient of the line joining (2, 3) and (6, 11).', '[{"key": "A", "text": "2"}, {"key": "B", "text": "4"}, {"key": "C", "text": "8"}, {"key": "D", "text": "½"}]'::jsonb, 'A', '(11 − 3) ÷ (6 − 2) = 2.', 1, 'medium', true),
    ('a329658c-6f30-5d2b-87cf-64373f6a950b', v_school, 'a2ed6252-37b9-513c-a254-0acc72d72690', 'mcq', 'Mathematics', 'SS3', 'Calculus', 'Differentiate y = 4x³ with respect to x.', '[{"key": "A", "text": "12x²"}, {"key": "B", "text": "4x²"}, {"key": "C", "text": "12x³"}, {"key": "D", "text": "x⁴"}]'::jsonb, 'A', 'dy/dx = 3 × 4x² = 12x².', 1, 'medium', true),
    ('1209122a-dfda-5c77-adec-7e73ff16a8a2', v_school, 'a2ed6252-37b9-513c-a254-0acc72d72690', 'mcq', 'Mathematics', 'SS3', 'Geometry', 'The sum of the interior angles of a hexagon is', '[{"key": "A", "text": "360°"}, {"key": "B", "text": "540°"}, {"key": "C", "text": "720°"}, {"key": "D", "text": "1080°"}]'::jsonb, 'C', '(6 − 2) × 180° = 720°.', 1, 'medium', true),
    ('93a2c23f-1f93-509f-b29f-e54e92060488', v_school, 'a2ed6252-37b9-513c-a254-0acc72d72690', 'mcq', 'Mathematics', 'SS3', 'Probability', 'If P(A) = 0.3, what is the probability that A does not happen?', '[{"key": "A", "text": "0.3"}, {"key": "B", "text": "0.7"}, {"key": "C", "text": "1.3"}, {"key": "D", "text": "0"}]'::jsonb, 'B', '1 − 0.3 = 0.7.', 1, 'easy', true),
    ('2f15c4a9-576e-5401-a5bf-7574d35ae04a', v_school, 'a2ed6252-37b9-513c-a254-0acc72d72690', 'mcq', 'Mathematics', 'SS3', 'Indices', 'Simplify (2³ × 2⁴) ÷ 2⁵', '[{"key": "A", "text": "2"}, {"key": "B", "text": "4"}, {"key": "C", "text": "8"}, {"key": "D", "text": "16"}]'::jsonb, 'B', '2^(3+4−5) = 2² = 4.', 1, 'medium', true),
    ('4a4d9f0a-3137-5e48-accc-dc71c272f20a', v_school, 'a2ed6252-37b9-513c-a254-0acc72d72690', 'mcq', 'Mathematics', 'SS3', 'Sequences and series', 'Find the 10th term of the sequence 3, 7, 11, 15, …', '[{"key": "A", "text": "39"}, {"key": "B", "text": "40"}, {"key": "C", "text": "43"}, {"key": "D", "text": "47"}]'::jsonb, 'A', 'a + 9d = 3 + 36 = 39.', 1, 'medium', true),
    ('29ad8ec0-db91-5106-93af-9cc2c235f7bd', v_school, 'a2ed6252-37b9-513c-a254-0acc72d72690', 'mcq', 'Mathematics', 'SS3', 'Quadratic equations', 'The roots of x² − 5x + 6 = 0 are', '[{"key": "A", "text": "2 and 3"}, {"key": "B", "text": "−2 and −3"}, {"key": "C", "text": "1 and 6"}, {"key": "D", "text": "−1 and 6"}]'::jsonb, 'A', '(x − 2)(x − 3) = 0.', 1, 'medium', true),
    ('543b4659-8c62-5833-b0ae-bc516050051e', v_school, 'a2ed6252-37b9-513c-a254-0acc72d72690', 'mcq', 'Mathematics', 'SS3', 'Statistics', 'Find the mean of 4, 8, 6, 10 and 12.', '[{"key": "A", "text": "6"}, {"key": "B", "text": "8"}, {"key": "C", "text": "10"}, {"key": "D", "text": "40"}]'::jsonb, 'B', '40 ÷ 5 = 8.', 1, 'easy', true),
    ('2532bd61-098a-53e1-aab9-1decf5257aa5', v_school, 'a2ed6252-37b9-513c-a254-0acc72d72690', 'true_false', 'Mathematics', 'SS3', 'Indices', 'The square root of 144 is 12.', '[{"key": "True", "text": "True"}, {"key": "False", "text": "False"}]'::jsonb, 'True', NULL, 1, 'easy', true),
